/**
 * gitpush.js
 *
 * Custom git commit + push endpoint for the Node-RED editor toolbar button.
 * Does NOT require the Node-RED Projects feature to be enabled in settings.
 *
 * Route: POST /gitpush
 * Body:  { "message": "commit message string" }
 *
 * Runs: git add -A  →  git commit -m "<message>"  →  git push
 * Working directory: settings.userDir (where flows.json lives)
 */

var spawn = require('child_process').spawn;
var path = require('path');
var os = require('os');
var log = require('@node-red/util').log;

var userDir;
var runtimeAPI;

/**
 * Resolve the git branch name using a two-level priority chain:
 *   1. Global env var  →  process.env.GIT_BRANCH
 *   2. Flow-level env var  →  tab's Environment Variables → GIT_BRANCH
 *   3. Fallback  →  sanitised tab label passed from the browser
 *
 * @param {string} tabId   - Node-RED tab/flow id sent by the browser
 * @param {string} fallback - sanitised branch name derived from the tab label
 * @param {Object} req      - Express request (for runtimeAPI audit logging)
 * @returns {Promise<string>} resolved branch name
 */
function resolveBranch(tabId, fallback, req) {
    // 1. Global env var takes highest priority
    if (process.env.GIT_BRANCH && process.env.GIT_BRANCH.trim().length > 0) {
        var globalBranch = process.env.GIT_BRANCH.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
        log.trace('[gitpush] Branch resolved from global env: ' + globalBranch);
        return Promise.resolve(globalBranch);
    }

    // 2. Flow-level env var — look up the tab's .env array via runtimeAPI
    if (tabId && runtimeAPI) {
        return runtimeAPI.flows.getFlow({ id: tabId, user: (req && req.user) || null, req: req })
            .then(function(flow) {
                if (flow && Array.isArray(flow.env)) {
                    var entry = flow.env.find(function(e) { return e.name === 'GIT_BRANCH'; });
                    if (entry && entry.value && entry.value.trim().length > 0) {
                        var flowBranch = entry.value.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
                        log.trace('[gitpush] Branch resolved from flow env (tab ' + tabId + '): ' + flowBranch);
                        return flowBranch;
                    }
                }
                log.trace('[gitpush] No flow-level GIT_BRANCH, using fallback: ' + fallback);
                return fallback;
            })
            .catch(function(err) {
                log.trace('[gitpush] Could not read flow env (tab ' + tabId + '), using fallback: ' + fallback);
                return fallback;
            });
    }

    // 3. Fallback — sanitised tab label from the browser
    log.trace('[gitpush] Branch fallback (no tabId/runtimeAPI): ' + fallback);
    return Promise.resolve(fallback);
}

/**
 * Run a single git command using spawn (avoids shell injection).
 * @param {string}   cmd   - executable, e.g. "git"
 * @param {string[]} args  - argument array, e.g. ["commit", "-m", "msg"]
 * @param {string}   cwd   - working directory
 * @returns {Promise<string>} stdout on success, rejects with stderr on non-zero exit
 */
function runGit(args, cwd) {
    return new Promise(function(resolve, reject) {
        var proc = spawn('git', args, { cwd: cwd });
        var stdout = '';
        var stderr = '';
        proc.stdout.on('data', function(d) { stdout += d.toString(); });
        proc.stderr.on('data', function(d) { stderr += d.toString(); });
        proc.on('close', function(code) {
            if (code !== 0) {
                reject({ code: code, stderr: stderr, stdout: stdout });
            } else {
                resolve(stdout);
            }
        });
        proc.on('error', function(err) {
            reject({ code: -1, stderr: err.message, stdout: '' });
        });
    });
}

module.exports = {
    init: function(settings, _runtimeAPI) {
        // Use settings.userDir if set, otherwise fall back to ~/.node-red (Node-RED default)
        userDir = settings.userDir || path.join(os.homedir(), '.node-red');
        runtimeAPI = _runtimeAPI;
        log.trace('[gitpush] userDir resolved to: ' + userDir);
    },

    post: function(req, res) {
        // Validate and sanitise commit message from request body
        var message = 'Node-RED flow update';
        if (req.body && typeof req.body.message === 'string' && req.body.message.trim().length > 0) {
            // Limit length to prevent oversized commit messages
            message = req.body.message.trim().substring(0, 500);
        }

        // tabId identifies which flow tab was active in the editor (sent by mybutton.js)
        var tabId = (req.body && typeof req.body.tabId === 'string') ? req.body.tabId.trim() : '';

        // Sanitised fallback branch from the browser (tab label → slugified).
        // Used only if neither global nor flow-level GIT_BRANCH env var is set.
        var fallbackBranch = 'flows';
        if (req.body && typeof req.body.branch === 'string' && req.body.branch.trim().length > 0) {
            fallbackBranch = req.body.branch.trim().replace(/[^a-zA-Z0-9\-\/]/g, '').substring(0, 100);
        }

        var dir = userDir;

        // Resolve branch via two-level priority: global env → flow env → fallback
        resolveBranch(tabId, fallbackBranch, req)
            .then(function(branch) {
                log.trace('[gitpush] Starting git commit+push in: ' + dir + ' branch: ' + branch + ' message: ' + message);

                // Step 1: stage only flows.json (not config files or settings)
                return runGit(['add', 'flows.json'], dir)
                    .then(function() {
                        // Step 2: commit
                        return runGit(['commit', '-m', message], dir);
                    })
                    .then(function(commitOut) {
                        // Step 3: push to the resolved branch.
                        // HEAD:<branch> means "push current HEAD to that branch on remote".
                        return runGit(['push', '--force', 'origin', 'HEAD:' + branch], dir).then(function(pushOut) {
                            log.trace('[gitpush] Push succeeded to origin/' + branch);
                            res.status(200).json({ success: true, branch: branch, output: commitOut + pushOut });
                        });
                    })
                    .catch(function(err) {
                        // "nothing to commit" — flows.json has not changed since last commit
                        if (err.stdout && err.stdout.indexOf('nothing to commit') !== -1) {
                            log.trace('[gitpush] Nothing to commit, pushing anyway');
                            runGit(['push', '--force', 'origin', 'HEAD:' + branch], dir)
                                .then(function(pushOut) {
                                    res.status(200).json({ success: true, branch: branch, output: 'Nothing to commit. ' + pushOut });
                                })
                                .catch(function(pushErr) {
                                    log.warn('[gitpush] Push failed: ' + pushErr.stderr);
                                    res.status(500).json({ error: pushErr.stderr || 'git push failed' });
                                });
                            return;
                        }
                        log.warn('[gitpush] Git error (code ' + err.code + '): ' + err.stderr);
                        res.status(500).json({ error: err.stderr || 'git operation failed' });
                    });
            });
    }
};
